    /**
     * Current security level (8 by default).
     */
    func level()  -> UInt8
    
}

/**
 * Portable, persistent TeamSpeak identity. The export string is the standard
 * TS3 identity format `"<counter>V<base64-key>"` — the same shape the official
 * client persists.
 */
open class IdentityObj:
    IdentityObjProtocol {
    fileprivate let pointer: UnsafeMutableRawPointer!

    /// Used to instantiate a [FFIObject] without an actual pointer, for fakes in tests, mostly.
    public struct NoPointer {
        public init() {}
    }

    // TODO: We'd like this to be `private` but for Swifty reasons,
    // we can't implement `FfiConverter` without making this `required` and we can't
    // make it `required` without making it `public`.
    required public init(unsafeFromRawPointer pointer: UnsafeMutableRawPointer) {
        self.pointer = pointer
    }

    /// This constructor can be used to instantiate a fake object.
    /// - Parameter noPointer: Placeholder value so we can have a constructor separate from the default empty one that may be implemented for classes extending [FFIObject].
    ///
    /// - Warning:
    ///     Any object instantiated with this constructor cannot be passed to an actual Rust-backed object. Since there isn't a backing [Pointer] the FFI lower functions will crash.
    public init(noPointer: NoPointer) {
        self.pointer = nil
    }

    public func uniffiClonePointer() -> UnsafeMutableRawPointer {
        return try! rustCall { uniffi_plnt_core_fn_clone_identityobj(self.pointer, $0) }
    }
    // No primary constructor declared for this class.

    deinit {
        guard let pointer = pointer else {
            return
        }

        try! rustCall { uniffi_plnt_core_fn_free_identityobj(pointer, $0) }
    }

    
    /**
     * Create a new identity with the default level (8).
     */
public static func create() -> IdentityObj {
    return try!  FfiConverterTypeIdentityObj.lift(try! rustCall() {
    uniffi_plnt_core_fn_constructor_identityobj_create($0
    )
})
}
    
    /**
     * Import a previously exported identity.
     */
public static func `import`(s: String)throws  -> IdentityObj {
    return try  FfiConverterTypeIdentityObj.lift(try rustCallWithError(FfiConverterTypePlntError.lift) {
    uniffi_plnt_core_fn_constructor_identityobj_import(
        FfiConverterString.lower(s),$0
    )
})
}
    

    
    /**
     * Export as a portable string. Round-trips through [`parse_identity`] —
     * and therefore through `import` and `Client::connect`, which both use it.
     *
     * The format is the standard TS3 identity string `"<counter>V<base64-key>"`,
     * the same shape the official client persists, so the counter (and with it
     * the hash-cash level) survives the round trip. The key half is
     * `base64(key.to_short())`, which is what tsproto's own `Serialize` impl
     * writes and what `EccKeyPrivP256::import_str` reads back.
     */
open func export() -> String {
    return try!  FfiConverterString.lift(try! rustCall() {
    uniffi_plnt_core_fn_method_identityobj_export(self.uniffiClonePointer(),$0
    )
})
}
    
    /**
     * Current security level (8 by default).
     */
open func level() -> UInt8 {
    return try!  FfiConverterUInt8.lift(try! rustCall() {
    uniffi_plnt_core_fn_method_identityobj_level(self.uniffiClonePointer(),$0
    )
})
}
    

}

public struct FfiConverterTypeIdentityObj: FfiConverter {

    typealias FfiType = UnsafeMutableRawPointer
    typealias SwiftType = IdentityObj

    public static func lift(_ pointer: UnsafeMutableRawPointer) throws -> IdentityObj {
        return IdentityObj(unsafeFromRawPointer: pointer)
    }

    public static func lower(_ value: IdentityObj) -> UnsafeMutableRawPointer {
        return value.uniffiClonePointer()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> IdentityObj {
        let v: UInt64 = try readInt(&buf)
        // The Rust code won't compile if a pointer won't fit in a UInt64.
        // We have to go via `UInt` because that's the thing that's the size of a pointer.
        let ptr = UnsafeMutableRawPointer(bitPattern: UInt(truncatingIfNeeded: v))
        if (ptr == nil) {
            throw UniffiInternalError.unexpectedNullPointer
        }
        return try lift(ptr!)
    }

    public static func write(_ value: IdentityObj, into buf: inout [UInt8]) {
        // This fiddling is because `Int` is the thing that's the same size as a pointer.
        // The Rust code won't compile if a pointer won't fit in a `UInt64`.
        writeInt(&buf, UInt64(bitPattern: Int64(Int(bitPattern: lower(value)))))
    }
}




public func FfiConverterTypeIdentityObj_lift(_ pointer: UnsafeMutableRawPointer) throws -> IdentityObj {
    return try FfiConverterTypeIdentityObj.lift(pointer)
}

public func FfiConverterTypeIdentityObj_lower(_ value: IdentityObj) -> UnsafeMutableRawPointer {
    return FfiConverterTypeIdentityObj.lower(value)
}


/**
 * A single channel in the TeamSpeak tree. Projects the bookkeeping `Channel`
 * into the minimum the app needs.
 */
public struct Channel {
    public var id: UInt64
    public var name: String
    public var parentId: UInt64?
    public var hasPassword: Bool
    /**
     * None means unlimited (or inherited; app shouldn't distinguish for v1).
     */
    public var maxClients: UInt32?
    public var talkPower: Int64
    public var codecLatencyFactor: UInt8
    public var codecIsOpusMusic: Bool

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(id: UInt64, name: String, parentId: UInt64?, hasPassword: Bool, 
        /**
         * None means unlimited (or inherited; app shouldn't distinguish for v1).
         */maxClients: UInt32?, talkPower: Int64, codecLatencyFactor: UInt8, codecIsOpusMusic: Bool) {
        self.id = id
        self.name = name
        self.parentId = parentId
        self.hasPassword = hasPassword
        self.maxClients = maxClients
        self.talkPower = talkPower
        self.codecLatencyFactor = codecLatencyFactor
        self.codecIsOpusMusic = codecIsOpusMusic
    }
}



extension Channel: Equatable, Hashable {
    public static func ==(lhs: Channel, rhs: Channel) -> Bool {
        if lhs.id != rhs.id {
            return false
        }
        if lhs.name != rhs.name {
            return false
        }
        if lhs.parentId != rhs.parentId {
            return false
        }
        if lhs.hasPassword != rhs.hasPassword {
            return false
        }
        if lhs.maxClients != rhs.maxClients {
            return false
        }
        if lhs.talkPower != rhs.talkPower {
            return false
        }
        if lhs.codecLatencyFactor != rhs.codecLatencyFactor {
            return false
        }
        if lhs.codecIsOpusMusic != rhs.codecIsOpusMusic {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(id)
        hasher.combine(name)
        hasher.combine(parentId)
        hasher.combine(hasPassword)
        hasher.combine(maxClients)
        hasher.combine(talkPower)
        hasher.combine(codecLatencyFactor)
        hasher.combine(codecIsOpusMusic)
    }
}


