/**
 * Where a text message came from / should be sent to. Server-wide chat and
 * pokes exist in the protocol but are out of scope for v1 (#3281) —
 * channel chat and client-to-client private messages only.
 */

public enum ChatTarget {
    
    case channel
    case client(clientId: UInt64
    )
}


public struct FfiConverterTypeChatTarget: FfiConverterRustBuffer {
    typealias SwiftType = ChatTarget

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ChatTarget {
