// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * All events the core emits to the sink. Flat enum over the variants the issue
 * specifies.
 */

public enum ConnEvent {
    
    case connected(ConnectionState
    )
    case disconnected(cause: DisconnectCause, reason: String
    )
    case channelTree([Channel]
    )
    /**
     * Full roster snapshot, not a delta — emitted once on connect and again
     * whenever the visible client set or its properties change.
     */
    case clientList([ClientInfo]
    )
    case clientMoved(clientId: UInt64, channelId: UInt64
    )
    case talkStatus(clientId: UInt64, talking: Bool
    )
    /**
     * 960 mono f32 samples at 48 kHz (20 ms) — jitter-buffered mixed mono.
     */
    case pcmFrame(clientId: UInt64, samples: [Float]
    )
    /**
     * Inbound channel or private text message.
     */
    case textMessage(target: ChatTarget, fromClientId: UInt64, fromName: String, text: String
    )
    case error(String
    )
    /**
     * tsclientlib is resending unacked packets and hasn't heard back yet. It
     * resolves this internally (reconnect + resume) without ever tearing the
     * `Client` down, so unlike `Disconnected` no `Connected` follows — the UI
     * must clear whatever this sets itself, once `Resumed` arrives.
     */
    case temporaryDisconnect(reason: String
    )
    /**
     * Emitted once, on the first `BookEvents` batch after a `TemporaryDisconnect`
     * resolves. tsclientlib's internal reconnect rebuilds its session state from
     * scratch, which can hand back a different `own_client_id` than before the
     * blip even though nothing about the app's session looks different from the
     * outside (#3277) — carrying the fresh id here is what lets the roster's
     * "(you)" row re-sync instead of silently going stale.
     */
    case resumed(ConnectionState
    )
    /**
     * PHA-3289: a raw server notification tsclientlib has no message type for,
     * surfaced as the command name plus its first-part key/value arguments,
     * already unescaped. Only the TS6 screen-share family (`notifystream*`,
     * `notifyjoinstreamrequest`, `notifyrespondjoinstreamrequest`) and
     * `error` replies that carry a `return_code` are forwarded; everything
     * tsclientlib already models keeps flowing through the typed events.
     * The viewer protocol itself lives on the Kotlin side, next to the
     * WebRTC stack that consumes the offer.
     */
    case rawCommand(name: String, args: [String: String]
    )
}


public struct FfiConverterTypeConnEvent: FfiConverterRustBuffer {
    typealias SwiftType = ConnEvent

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> ConnEvent {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .connected(try FfiConverterTypeConnectionState.read(from: &buf)
        )
        
        case 2: return .disconnected(cause: try FfiConverterTypeDisconnectCause.read(from: &buf), reason: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .channelTree(try FfiConverterSequenceTypeChannel.read(from: &buf)
        )
        
        case 4: return .clientList(try FfiConverterSequenceTypeClientInfo.read(from: &buf)
        )
        
        case 5: return .clientMoved(clientId: try FfiConverterUInt64.read(from: &buf), channelId: try FfiConverterUInt64.read(from: &buf)
        )
        
        case 6: return .talkStatus(clientId: try FfiConverterUInt64.read(from: &buf), talking: try FfiConverterBool.read(from: &buf)
        )
        
        case 7: return .pcmFrame(clientId: try FfiConverterUInt64.read(from: &buf), samples: try FfiConverterSequenceFloat.read(from: &buf)
        )
        
        case 8: return .textMessage(target: try FfiConverterTypeChatTarget.read(from: &buf), fromClientId: try FfiConverterUInt64.read(from: &buf), fromName: try FfiConverterString.read(from: &buf), text: try FfiConverterString.read(from: &buf)
        )
        
        case 9: return .error(try FfiConverterString.read(from: &buf)
        )
        
        case 10: return .temporaryDisconnect(reason: try FfiConverterString.read(from: &buf)
        )
        
        case 11: return .resumed(try FfiConverterTypeConnectionState.read(from: &buf)
        )
        
        case 12: return .rawCommand(name: try FfiConverterString.read(from: &buf), args: try FfiConverterDictionaryStringString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ConnEvent, into buf: inout [UInt8]) {
        switch value {
        
        
        case let .connected(v1):
            writeInt(&buf, Int32(1))
            FfiConverterTypeConnectionState.write(v1, into: &buf)
            
        
        case let .disconnected(cause,reason):
            writeInt(&buf, Int32(2))
            FfiConverterTypeDisconnectCause.write(cause, into: &buf)
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .channelTree(v1):
            writeInt(&buf, Int32(3))
            FfiConverterSequenceTypeChannel.write(v1, into: &buf)
            
        
        case let .clientList(v1):
            writeInt(&buf, Int32(4))
            FfiConverterSequenceTypeClientInfo.write(v1, into: &buf)
            
        
        case let .clientMoved(clientId,channelId):
            writeInt(&buf, Int32(5))
            FfiConverterUInt64.write(clientId, into: &buf)
            FfiConverterUInt64.write(channelId, into: &buf)
            
        
        case let .talkStatus(clientId,talking):
            writeInt(&buf, Int32(6))
            FfiConverterUInt64.write(clientId, into: &buf)
            FfiConverterBool.write(talking, into: &buf)
            
        
        case let .pcmFrame(clientId,samples):
            writeInt(&buf, Int32(7))
            FfiConverterUInt64.write(clientId, into: &buf)
            FfiConverterSequenceFloat.write(samples, into: &buf)
            
        
        case let .textMessage(target,fromClientId,fromName,text):
            writeInt(&buf, Int32(8))
            FfiConverterTypeChatTarget.write(target, into: &buf)
            FfiConverterUInt64.write(fromClientId, into: &buf)
            FfiConverterString.write(fromName, into: &buf)
            FfiConverterString.write(text, into: &buf)
            
        
        case let .error(v1):
            writeInt(&buf, Int32(9))
            FfiConverterString.write(v1, into: &buf)
            
        
        case let .temporaryDisconnect(reason):
            writeInt(&buf, Int32(10))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .resumed(v1):
            writeInt(&buf, Int32(11))
            FfiConverterTypeConnectionState.write(v1, into: &buf)
            
        
        case let .rawCommand(name,args):
            writeInt(&buf, Int32(12))
            FfiConverterString.write(name, into: &buf)
            FfiConverterDictionaryStringString.write(args, into: &buf)
            
        }
    }
}


public func FfiConverterTypeConnEvent_lift(_ buf: RustBuffer) throws -> ConnEvent {
    return try FfiConverterTypeConnEvent.lift(buf)
}

public func FfiConverterTypeConnEvent_lower(_ value: ConnEvent) -> RustBuffer {
    return FfiConverterTypeConnEvent.lower(value)
}



