// Note that we don't yet support `indirect` for enums.
// See https://github.com/mozilla/uniffi-rs/issues/396 for further discussion.
/**
 * Why a connection ended, as far as the core can tell the cases apart.
 *
 * #3283: `Disconnected` used to carry only a reason string, and the
 * app-requested exit hardcoded `"client.disconnect"`. Downstream that was
 * indistinguishable from the user hanging up, which is what blocked diagnosis
 * of the #3238 drop. The core deliberately does not model *why the app
 * asked* — it cannot know — so the Android layer widens this into its own
 * `DisconnectCause` (see `CoreBridge.kt`) with the causes only it can see,
 * such as Android reclaiming the foreground service.
 */

public enum DisconnectCause {
    
    /**
     * [`crate::Client::disconnect`] was called: the connection loop exited
     * because this app asked it to. Says nothing about who or what inside
     * the app asked.
     */
    case requested
    /**
     * The event stream ended under us — server shutdown/kick, or the
     * transport died. Nobody on this side asked for it.
     */
    case connectionLost
}


public struct FfiConverterTypeDisconnectCause: FfiConverterRustBuffer {
    typealias SwiftType = DisconnectCause

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> DisconnectCause {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .requested
        
        case 2: return .connectionLost
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: DisconnectCause, into buf: inout [UInt8]) {
        switch value {
        
        
        case .requested:
            writeInt(&buf, Int32(1))
        
        
        case .connectionLost:
            writeInt(&buf, Int32(2))
        
        }
    }
}


public func FfiConverterTypeDisconnectCause_lift(_ buf: RustBuffer) throws -> DisconnectCause {
    return try FfiConverterTypeDisconnectCause.lift(buf)
}

public func FfiConverterTypeDisconnectCause_lower(_ value: DisconnectCause) -> RustBuffer {
    return FfiConverterTypeDisconnectCause.lower(value)
}



extension DisconnectCause: Equatable, Hashable {}




/**
 * Error type surfaced through UniFFI.
 */
public enum PlntError {

    
    
    case NotConnected(message: String)
    
    case Identity(message: String)
    
    case Connection(message: String)
    
    case Audio(message: String)
    
    case Invalid(message: String)
    
}


public struct FfiConverterTypePlntError: FfiConverterRustBuffer {
    typealias SwiftType = PlntError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> PlntError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .NotConnected(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 2: return .Identity(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 3: return .Connection(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 4: return .Audio(
            message: try FfiConverterString.read(from: &buf)
        )
        
        case 5: return .Invalid(
            message: try FfiConverterString.read(from: &buf)
        )
        

        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

