private enum InitializationResult {
    case ok
    case contractVersionMismatch
    case apiChecksumMismatch
}
// Use a global variables to perform the versioning checks. Swift ensures that
// the code inside is only computed once.
private var initializationResult: InitializationResult {
    // Get the bindings contract version from our ComponentInterface
    let bindings_contract_version = 26
    // Get the scaffolding contract version by calling the into the dylib
    let scaffolding_contract_version = ffi_plnt_core_uniffi_contract_version()
    if bindings_contract_version != scaffolding_contract_version {
        return InitializationResult.contractVersionMismatch
    }
    if (uniffi_plnt_core_checksum_func_core_version() != 48360) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_method_client_connect() != 26877) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_method_client_disconnect() != 49375) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_method_client_join_channel() != 32077) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_method_client_send_pcm_frame() != 52815) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_method_client_send_raw_command() != 41139) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_method_client_send_text_message() != 14005) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_method_client_set_input_muted() != 20064) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_method_client_set_output_muted() != 36648) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_method_identityobj_export() != 42603) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_method_identityobj_level() != 11117) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_constructor_client_new() != 40795) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_constructor_identityobj_create() != 109) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_constructor_identityobj_import() != 51032) {
        return InitializationResult.apiChecksumMismatch
    }
    if (uniffi_plnt_core_checksum_method_eventsink_on_event() != 36507) {
        return InitializationResult.apiChecksumMismatch
    }

    uniffiCallbackInitEventSink()
    return InitializationResult.ok
}

private func uniffiEnsureInitialized() {
    switch initializationResult {
    case .ok:
        break
    case .contractVersionMismatch:
        fatalError("UniFFI contract version mismatch: try cleaning and rebuilding your project")
    case .apiChecksumMismatch:
        fatalError("UniFFI API checksum mismatch: try cleaning and rebuilding your project")
    }
}

